        else:
            # fallback toward center
            dx = 1 if center_x > 0 else -1 if center_x < 0 else 0
            dy = 1 if center_y > 0 else -1 if center_y < 0 else 0

    elif mode == "pursuit_evasion":
        target = get_int_list("nearest_evader", None)
        if target is None:
