        else:
            dx = -1 if center_x > 0 else 1 if center_x < 0 else 0
            dy = -1 if center_y > 0 else 1 if center_y < 0 else 0

    elif mode == "territory_control":
        # Try to move toward the least controlled quadrant or center
        # Use a simple heuristic: move toward center to stabilize
        dx = -1 if center_x > 0 else (1 if center_x < 0 else 0)
        dy = -1 if center_y > 0 else (1 if center_y < 0 else 0)
        # If there is a hint of an enemy or rival nearby, adjust to anti-approach
        rival = get_int_list("nearest_rival", None)
        if rival is not None:
            rx, ry = rival
            if rx == 0 and ry == 0:
                dx, dy = 0, 0
            else:
                dx = -1 if rx > 0 else (1 if rx < 0 else 0)
                dy = -1 if ry > 0 else (1 if ry < 0 else 0)

    else:
        # Unknown mode: move toward center as a safe default
        dx = -1 if center_x > 0 else (1 if center_x < 0 else 0)
        dy = -1 if center_y > 0 else (1 if center_y < 0 else 0)

    # Clip to allowed range (-1, 0, 1)
    if dx not in (-1, 0, 1):
        dx = 0
    if dy not in (-1, 0, 1):
        dy = 0

